private byte[] canonicalEnvelope(int level, byte[] dcid, byte[] scid, byte[] token, int keyPhase, long pn, long expected, byte[] payload) {
    int width = choosePnWidth(pn, expected);
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    if (level < 2) {
