        out.write(first);
        out.write(0); out.write(0); out.write(0); out.write(1);   // version
        out.write(dcid.length); out.write(dcid);
        out.write(scid.length); out.write(scid);
        if (level == 0) { byte[] t = QuicVarint.encode(token.length); out.write(t); out.write(token); }
        long length = width + payload.length;
        byte[] l = QuicVarint.encode(length); out.write(l);
        writePn(out, pn, width);
        out.write(payload);
    } else {
        int first = 0x40 | (keyPhase << 2) | (width - 1);
        out.write(first);
        out.write(dcid);
        writePn(out, pn, width);
        out.write(payload);
    }
    return out.toByteArray();
}
